def choose_move(observation):
    def sign(v):
        return 1 if v > 0 else (-1 if v < 0 else 0)

    def get_pos(key, default=(0, 0)):
        p = observation.get(key, default)
        if isinstance(p, (list, tuple)) and len(p) >= 2:
            return p[0], p[1]
        return default

    def step_toward(src, dst):
        return [sign(dst[0] - src[0]), sign(dst[1] - src[1])]

    def step_away(src, dst):
        return [sign(src[0] - dst[0]), sign(src[1] - dst[1])]

    def nearest(points, src):
        best = None
        best_d = None
        for p in points or []:
            if isinstance(p, (list, tuple)) and len(p) >= 2:
                d = abs(p[0] - src[0]) + abs(p[1] - src[1])
                if best is None or d < best_d:
                    best = (p[0], p[1])
                    best_d = d
        return best

    def farthest(points, src):
        best = None
        best_d = None
        for p in points or []:
            if isinstance(p, (list, tuple)) and len(p) >= 2:
                d = abs(p[0] - src[0]) + abs(p[1] - src[1])
                if best is None or d > best_d:
                    best = (p[0], p[1])
                    best_d = d
        return best

    env = observation.get("environment_name", "")
    sx, sy = get_pos("self_position")
    ox, oy = get_pos("opponent_position", (sx, sy))
    self_pos = (sx, sy)
    opp_pos = (ox, oy)

    if env == "pursuit_evasion":
        role = observation.get("self_role", "pursuer")
        if role == "pursuer":
            return step_toward(self_pos, opp_pos)
        w = observation.get("grid_width", 0) or 0
        h = observation.get("grid_height", 0) or 0
        corners = [(0, 0), (0, max(0, h - 1)), (max(0, w - 1), 0), (max(0, w - 1), max(0, h - 1))]
        target = farthest(corners, opp_pos) or (sx, sy)
        return step_toward(self_pos, target)

    if env == "territory_control":
        targets = observation.get("unclaimed_cells") or observation.get("opponent_territory") or observation.get("frontier") or []
        target = nearest(targets, self_pos)
        if target is not None:
            return step_toward(self_pos, target)
        # fallback: move toward center or opponent
        w = observation.get("grid_width", 0) or 0
        h = observation.get("grid_height", 0) or 0
        if w and h:
            return step_toward(self_pos, (w // 2, h // 2))
        return step_toward(self_pos, opp_pos)

    resources = observation.get("resources") or observation.get("resource_positions") or observation.get("items") or []
    target = nearest(resources, self_pos)
    if target is not None:
        return step_toward(self_pos, target)

    # Fallbacks when no resources are visible
    if env == "resource_collection":
        return step_toward(self_pos, opp_pos)
    return [0, 0]

